func mustTrailResumeIntegrationHost(t *testing.T, rawURL string) string {
	t.Helper()
	parsed, err := url.Parse(rawURL)
	if err != nil {
		t.Fatalf("parse URL %q: %v", rawURL, err)
	}
	if parsed.Host == "" {
		t.Fatalf("URL %q has no host", rawURL)
	}
	return parsed.Host
}

