	t.Parallel()

	cmd := newTrailResumeCmd()
	cmd.SetOut(&bytes.Buffer{})
	cmd.SetErr(&bytes.Buffer{})
	cmd.SetArgs([]string{"575", "--trail", "feature/a"})

	err := cmd.Execute()
	if err == nil {
		t.Fatal("expected error combining positional trail with --trail, got nil")
