/**
 * Derive the overall review status from a list of reviewers.
 * "changes_requested" if any reviewer requested changes.
 * "approved" only if there is at least one reviewer with a non-pending
 * status and ALL of their latest statuses are "approved".
 */
function deriveReviewStatus(
  reviewers?: { status: string }[],
): "approved" | "changes_requested" | null {
  if (!reviewers?.length) return null
  const decided = reviewers.filter((r) => r.status !== "pending")
  if (decided.length === 0) return null
  if (decided.some((r) => r.status === "changes_requested")) return "changes_requested"
  if (decided.every((r) => r.status === "approved")) return "approved"
  return null
}

