const CODE_TOOLS = new Set(["Edit", "Write", "NotebookEdit"])
const TOOL_CATEGORY_DOT_CLASS: Record<string, string> = {
  "File edits": "bg-green-500 dark:bg-green-400",
  Bash: "bg-amber-500 dark:bg-amber-400",
  Read: "bg-sky-500 dark:bg-sky-400",
  Other: "bg-neutral-400 dark:bg-neutral-500",
}

function getToolCategory(name: string): string {
  if (CODE_TOOLS.has(name)) return "File edits"
  if (name === "Bash") return "Bash"
  if (name === "Read" || name === "Grep" || name === "Glob") return "Read"
  return "Other"
}

function getToolCategoryDotClass(name: string): string {
  return TOOL_CATEGORY_DOT_CLASS[getToolCategory(name)] ?? TOOL_CATEGORY_DOT_CLASS.Other
}

interface SessionDetailProps {
  session: SessionTranscript
  authorUsername: string
  activated?: boolean
}

export function SessionDetail({ session, authorUsername, activated }: SessionDetailProps) {
  const [expanded, setExpanded] = useState(true)

  if (activated && !expanded) {
    setExpanded(true)
  }

  const agentConfig = getAgent(session.agent)
  const startTime = session.messages[0]?.timestamp
  const endTime = session.messages[session.messages.length - 1]?.timestamp
  const duration = startTime && endTime ? formatDuration(startTime, endTime) : null
  const stepCount = session.messages.length
  const toolCount = session.messages.some((msg) => msg.toolCalls !== undefined)
    ? session.messages.reduce((sum, msg) => sum + (msg.toolCalls?.length ?? 0), 0)
    : null
  const totalTokens = session.tokenUsage
    ? session.tokenUsage.inputTokens + session.tokenUsage.outputTokens
    : null

  const Chevron = expanded ? ChevronDown : ChevronRight

  return (
    <div
      id={`session-${session.sessionId}`}
      className="min-w-0 flex-1 scroll-mt-[calc(var(--global-header-height)+1rem)]"
