  const baseSlug = slugify(text)
  const allReservedIds = [...existingIds, ...RESERVED_TAB_IDS]

  if (
    (!allReservedIds.includes(baseSlug) || baseSlug === currentId) &&
    !RESERVED_TAB_IDS.includes(baseSlug)
  ) {
    return baseSlug
  }

  let counter = 2
  while (
    allReservedIds.includes(`${baseSlug}-${counter}`) &&
    `${baseSlug}-${counter}` !== currentId
  ) {
    counter++
  }
  return `${baseSlug}-${counter}`
}

