function getMergeBlockReason(m: TrailMergeability): string {
  const reasons: string[] = []
  if (!m.reviews_approved) reasons.push("Reviews not approved")
  if (!m.checks_passed) reasons.push(`CI checks ${m.checks_status}`)
  if (m.has_conflicts) reasons.push("Branch has diverged from base")
  return reasons.join(", ") || "Not ready to merge"
}

