function groupCheckpointsIntoCommits(checkpoints: CheckpointInfo[]): CommitInfo[] {
  const commitMap = new Map<string, CommitInfo>()
  for (const cp of checkpoints) {
    let commit = commitMap.get(cp.commitSha)
    if (!commit) {
      commit = {
        commitSha: cp.commitSha,
        commitMessage: cp.commitMessage,
        commitAuthor: cp.commitAuthor,
        commitAuthorUsername: cp.commitAuthorUsername,
        commitDate: cp.commitDate,
        additions: cp.additions,
        deletions: cp.deletions,
        filesChanged: cp.fileStats?.length ?? null,
        filesTouched: cp.filesTouched,
        fileStats: cp.fileStats,
        url: null,
        checkpoints: [],
      }
      commitMap.set(cp.commitSha, commit)
    }
    commit.checkpoints.push(cp)
  }
  return Array.from(commitMap.values())
}

function ChangesSection({
  org,
  repo,
  checkpoints,
}: {
  org: string
  repo: string
  trail: TrailDetail
  checkpoints: CheckpointInfo[]
}) {
