}: CheckpointSidebarProps) {
  const { treeItems, defaultExpanded, fileMap } = useMemo(
    () => buildFileTree(fileStats ?? []),
    [fileStats],
  )

  const handleFileClick = (item: TreeItemData) => {
    const file = fileMap.get(item.id)
    if (!file) return
    onSelectFile(file.filename)
  }

  return (
    <div className="flex w-full flex-col gap-6 overflow-y-auto lg:sticky lg:top-[calc(var(--global-header-height)+1rem)] lg:max-h-[calc(100vh-var(--global-header-height)-2rem)] lg:w-82 lg:shrink-0 lg:self-start lg:pr-4">
      {showSessions && (
        <div>
          <h3 className="mb-2 flex items-center gap-1.5 px-1 font-mono text-xs text-muted uppercase">
            <span>Sessions</span>
            <Badge size="icon">{sessions.length}</Badge>
          </h3>
          <div className="flex flex-col gap-1.5">
            {isTranscriptLoading ? (
              Array.from({ length: 2 }).map((_, i) => <SessionCardSkeleton key={i} />)
            ) : sessions.length > 0 ? (
              sessions.map((session) => (
                <SessionCard
                  key={session.sessionId}
                  session={session}
                  isSelected={activeId === `session-${session.sessionId}`}
                  onSelect={() => onSelectSession(session.sessionId)}
                />
              ))
            ) : (
              <div className="px-1 text-xs text-muted">No sessions</div>
            )}
          </div>
        </div>
      )}

      {/* Files section - TreeView (hidden while sessions are loading) */}
      {!isTranscriptLoading && treeItems.length > 0 && (
        <div className="min-w-0">
          <h3 className="mb-2 flex items-center gap-1.5 px-1 font-mono text-xs text-muted uppercase">
            <span>Files</span>
            <Badge size="icon">{fileStats?.length ?? 0}</Badge>
          </h3>
          <Tree
            defaultExpandedItems={defaultExpanded}
