            onItemClick={handleFileClick}
            showIndentGuides
          >
            {treeItems.map((node) => (
              <FileTreeNode key={node.path} node={node} />
            ))}
          </Tree>
        </div>
      )}
    </div>
  )
}

function SessionCard({
  session,
  isSelected,
  onSelect,
}: {
  session: SessionTranscript
  isSelected: boolean
  onSelect: () => void
}) {
  const agentConfig = getAgent(session.agent)
  // Messages come pre-processed from the API (filtered and tags stripped)
  const stepCount = session.messages.length
  const firstUserMessage = session.messages.find((m) => m.role === "user")
  const preview = firstUserMessage?.content?.trim() || null

  return (
    <button
      type="button"
      onClick={onSelect}
      className={`w-full cursor-pointer rounded px-3 py-2.5 text-left transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-focus focus-visible:ring-inset ${
        isSelected ? "bg-selected" : "hover:bg-hover"
      }`}
    >
      <div className="flex items-center justify-between gap-2">
        <div className="flex min-w-0 items-center gap-2">
          <AgentAvatar agent={session.agent} className="size-5" />
          <span className="truncate text-sm font-semibold text-default">{agentConfig.label}</span>
        </div>
        {stepCount > 0 && <span className="shrink-0 text-xs text-muted">{stepCount} steps</span>}
      </div>
      {preview && <p className="mt-1 ml-7 line-clamp-2 text-sm text-muted">{preview}</p>}
    </button>
  )
}

function SessionCardSkeleton() {
