import {
  FloatingFocusManager,
  FloatingOverlay,
  FloatingPortal,
  FloatingContext,
  useTransitionStatus,
  useDismiss,
  useFloating,
  useInteractions,
  useRole,
  autoUpdate,
} from "@floating-ui/react"
import { clsx } from "clsx"
import {
  ButtonHTMLAttributes,
  HTMLAttributes,
  ReactElement,
  ReactNode,
  Ref,
  RefObject,
  cloneElement,
  createContext,
  isValidElement,
  useCallback,
  useContext,
  useEffect,
  useId,
  useMemo,
  useState,
} from "react"

import Button from "./Button"

interface DialogContextValue {
  open: boolean
  setOpen: (open: boolean) => void
  context: FloatingContext
  refs: ReturnType<typeof useFloating>["refs"]
  getFloatingProps: (userProps?: React.HTMLProps<HTMLElement>) => Record<string, unknown>
  labelId?: string
  descriptionId?: string
  setLabelId: (id?: string) => void
  setDescriptionId: (id?: string) => void
}

const DialogContext = createContext<DialogContextValue | null>(null)

const useDialogContext = () => {
  const context = useContext(DialogContext)
  if (!context) {
    throw new Error("Dialog components must be used within a Dialog")
  }
  return context
}

type SetStateFn = (open: boolean) => void

interface DialogProps {
  children: ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: SetStateFn
}

const composeEventHandlers =
  <Event extends { defaultPrevented: boolean }>(
    theirHandler: ((event: Event) => void) | undefined,
    ourHandler: (event: Event) => void,
  ) =>
  (event: Event) => {
    theirHandler?.(event)
    if (!event.defaultPrevented) {
      ourHandler(event)
    }
  }

export function Dialog({ children, open: controlledOpen, defaultOpen, onOpenChange }: DialogProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen ?? false)
  const open = controlledOpen ?? uncontrolledOpen

  const setOpen = useCallback<SetStateFn>(
    (nextOpen) => {
      if (controlledOpen === undefined) {
        setUncontrolledOpen(nextOpen)
      }
      onOpenChange?.(nextOpen)
    },
    [controlledOpen, onOpenChange],
  )

  const { context, refs } = useFloating({
    open,
    onOpenChange: setOpen,
    whileElementsMounted: autoUpdate,
  })

  const dismiss = useDismiss(context, {
    outsidePress: true,
    escapeKey: true,
  })
  const role = useRole(context, { role: "dialog" })

  const { getFloatingProps } = useInteractions([dismiss, role])

  const [labelId, setLabelId] = useState<string>()
  const [descriptionId, setDescriptionId] = useState<string>()

  const value = useMemo<DialogContextValue>(
    () => ({
      open,
      setOpen,
      context,
      refs,
      getFloatingProps,
      labelId,
      descriptionId,
      setLabelId,
      setDescriptionId,
    }),
    [open, setOpen, context, refs, getFloatingProps, labelId, descriptionId],
  )

  return <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
}

interface DialogTriggerProps {
  children: ReactNode
  asChild?: boolean
}

export function DialogTrigger({ children, asChild }: DialogTriggerProps) {
  const { refs, setOpen, open, context } = useDialogContext()

  if (asChild) {
    if (!isValidElement(children)) {
      throw new Error("DialogTrigger with asChild requires a single React element child")
    }
    const child = children as ReactElement<{
      onClick?: (event: React.MouseEvent) => void
    }>
    return cloneElement(child, {
      ref: refs.setReference,
      onClick: composeEventHandlers(child.props.onClick, () => setOpen(true)),
      "aria-haspopup": "dialog",
      "aria-expanded": open,
      "aria-controls": context?.floatingId,
    } as Record<string, unknown>)
  }

  return (
    <Button
      ref={refs.setReference as Ref<HTMLButtonElement>}
      onClick={() => setOpen(true)}
      aria-haspopup="dialog"
      aria-expanded={open}
      aria-controls={context?.floatingId}
    >
      {children}
    </Button>
  )
}

interface DialogContentProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode
  className?: string
  overlayClassName?: string
  initialFocus?: number | RefObject<HTMLElement | null>
  /** Whether to apply default padding. Defaults to true. */
  padding?: boolean
}

export function DialogContent({
  children,
  className,
  overlayClassName,
  initialFocus,
  padding = true,
  ...props
}: DialogContentProps) {
  const { context, refs, getFloatingProps, labelId, descriptionId } = useDialogContext()

  const animationDuration = 150

  const { isMounted, status } = useTransitionStatus(context, {
    duration: animationDuration,
  })

  if (!isMounted) return null

  const isOpening = status === "initial" || status === "open"

  return (
    <FloatingPortal>
      <>
        <FloatingOverlay
          lockScroll
          className={clsx(
            "fixed inset-0 z-modal bg-neutral-950/60 backdrop-blur-xs transition-opacity duration-150 ease-out",
            isOpening ? "opacity-100" : "opacity-0",
            overlayClassName,
          )}
        />
        <FloatingFocusManager context={context} modal restoreFocus initialFocus={initialFocus}>
          <div
            className={clsx(
              "fixed inset-0 z-dialog flex items-center justify-center p-4 transition-opacity duration-150 ease-out",
              isOpening ? "opacity-100" : "pointer-events-none opacity-0",
            )}
          >
            <div
              ref={refs.setFloating}
              className={clsx(
                "w-full max-w-lg rounded-lg bg-white shadow-xl ring-1 ring-border backdrop-blur-xs transition-[transform,opacity] duration-150 ease-out focus:outline-hidden dark:bg-neutral-800",
                padding && "p-5",
                isOpening ? "scale-100 opacity-100" : "scale-95 opacity-0",
                className,
              )}
              role="dialog"
              aria-modal="true"
              aria-labelledby={labelId}

