import type { Placement } from "@floating-ui/react"
import { Link } from "@tanstack/react-router"
import { clsx } from "clsx"
import {
  ReactNode,
  ButtonHTMLAttributes,
  AnchorHTMLAttributes,
  Children,
  isValidElement,
  Ref,
} from "react"

import Tooltip from "./Tooltip"

const sizeStyles = {
  small: { base: "h-8 text-sm font-normal", padding: "px-3" },
  medium: { base: "h-9 text-sm", padding: "px-4" },
  large: { base: "h-12 text-base", padding: "px-6" },
  icon: "size-9 shrink-0",
  "icon-small": "size-8 shrink-0",
}

const variantStyles = {
  outline: "bg-raised text-default hover:bg-hover active:bg-active border border-default",
  ghost: "bg-transparent text-default hover:bg-hover active:bg-active border border-transparent",
  attention:
    "bg-neutral-900 dark:bg-neutral-100 text-white dark:text-neutral-900 hover:bg-neutral-800 dark:hover:bg-neutral-200 active:bg-neutral-700 dark:active:bg-neutral-300 focus-visible:[box-shadow:inset_0_0_0_4px_white] dark:focus-visible:[box-shadow:inset_0_0_0_4px_rgb(23_23_23)]",
  danger:
    "text-red-700 dark:text-red-400 hover:bg-red-700 dark:hover:bg-red-800 hover:text-white active:bg-red-800 dark:active:bg-red-900 border border-red-700 dark:border-red-600",
}

const baseStyles =
  "flex items-center justify-center gap-1.5 rounded font-medium transition-colors duration-150 focus:transition-none cursor-pointer min-w-0 disabled:opacity-50 disabled:cursor-not-allowed disabled:pointer-events-none focus:outline-2 focus:-outline-offset-2 focus:outline-transparent focus-visible:outline-focus"

type Size = keyof typeof sizeStyles
type Variant = keyof typeof variantStyles

interface BaseButtonProps {
  size?: Size
  variant?: Variant
  condensed?: boolean
  className?: string
  children: ReactNode
  disabled?: boolean
  tooltipPosition?: Placement
  ref?: Ref<HTMLButtonElement | HTMLAnchorElement>
}

interface ButtonAsButton
  extends BaseButtonProps, Omit<ButtonHTMLAttributes<HTMLButtonElement>, keyof BaseButtonProps> {
  href?: never
  to?: never
}

interface ButtonAsLink
  extends BaseButtonProps, Omit<AnchorHTMLAttributes<HTMLAnchorElement>, keyof BaseButtonProps> {
  href: string
  to?: never
}

interface ButtonAsRouterLink extends BaseButtonProps {
  to: string
  href?: never
  target?: string
  rel?: string
}

type ButtonProps = ButtonAsButton | ButtonAsLink | ButtonAsRouterLink

export function Button({
  size = "medium",
  variant = "outline",
  condensed = false,
  className,
  children,
  disabled,
  tooltipPosition,
  ref,
  ...rest
}: ButtonProps) {
  const isIconButton = size === "icon" || size === "icon-small"

  const classes = clsx(
    baseStyles,
    isIconButton ? sizeStyles[size] : sizeStyles[size].base,
    !isIconButton && !condensed && sizeStyles[size].padding,
    !isIconButton && condensed && "px-2",
    variantStyles[variant],
    className,
  )

  // Check if children contains mixed content (icon + text)
  const childArray = Children.toArray(children)
  const hasMultipleChildren = childArray.length > 1
  const hasIconChild = childArray.some((child) => isValidElement(child) && child.type !== "string")

  const content = isIconButton ? (
    children
  ) : hasMultipleChildren && hasIconChild ? (
    // Button with icon + text: wrap only text nodes in truncate span, prevent icon from shrinking
    <>
      {childArray.map((child, index) =>
        isValidElement(child) ? (
          <span key={index} className="shrink-0">
            {child}
          </span>
        ) : (
          <span key={index} className="min-w-0 truncate">
            {child}
          </span>
        ),
      )}
    </>
  ) : (
    // Text-only button: wrap everything in truncate span
    <span className="min-w-0 truncate">{children}</span>
  )

  // Router link
  if ("to" in rest && rest.to) {
    const routerLinkProps = rest as ButtonAsRouterLink
    const link = (
      <Link
        to={routerLinkProps.to}
        target={routerLinkProps.target}
        rel={routerLinkProps.rel}
        className={classes}
        aria-disabled={disabled}
      >
        {content}
      </Link>
    )

    if (isIconButton && routerLinkProps["aria-label" as keyof typeof routerLinkProps]) {
      return (
        <Tooltip
          text={routerLinkProps["aria-label" as keyof typeof routerLinkProps] as string}
          relationship="label"
          position={tooltipPosition}
        >
          {link}
        </Tooltip>
      )
    }

    return link
  }

  // External link
  if ("href" in rest && rest.href) {
    const linkProps = rest as ButtonAsLink
    const link = (
      <a
        ref={ref as React.Ref<HTMLAnchorElement>}
        href={linkProps.href}
        target={linkProps.target}
        rel={linkProps.rel}
        className={classes}
        aria-disabled={disabled}
        onClick={disabled ? undefined : linkProps.onClick}
        {...(linkProps as AnchorHTMLAttributes<HTMLAnchorElement>)}
      >
        {content}
      </a>
    )

    // Wrap icon buttons with tooltip if they have aria-label
    if (isIconButton && linkProps["aria-label"]) {
      return (
        <Tooltip text={linkProps["aria-label"]} relationship="label" position={tooltipPosition}>
          {link}
        </Tooltip>
      )
    }

    return link
  }

  // Button
  const buttonProps = rest as ButtonAsButton
  const button = (
    <button
      ref={ref as React.Ref<HTMLButtonElement>}
      type={buttonProps.type || "button"}
      onClick={buttonProps.onClick}
      disabled={disabled}
      className={classes}
      {...(buttonProps as ButtonHTMLAttributes<HTMLButtonElement>)}
    >
      {content}
    </button>
  )

  // Wrap icon buttons with tooltip if they have aria-label
  if (isIconButton && buttonProps["aria-label"]) {
    return (
      <Tooltip text={buttonProps["aria-label"]} relationship="label" position={tooltipPosition}>
        {button}
      </Tooltip>
    )
  }

  return button
}

export default Button

