  const allSubTriggers = screen.getAllByTestId("dropdown-sub-trigger")
  const assigneeTrigger = allSubTriggers.find((el) => el.textContent === "Assignee")
  if (!assigneeTrigger) return null
  const subContent = assigneeTrigger
    .closest('[data-testid="dropdown-sub"]')
    ?.querySelector('[data-testid="dropdown-sub-content"]')
  if (!subContent) return null
  return Array.from(subContent.querySelectorAll('[role="menuitem"]')).find(
    (el) => el.textContent === name,
  ) as HTMLElement | null
}

