  const { refs, floatingStyles, context, isPositioned } = useFloating({
    open: isOpen && !disabled,
    onOpenChange: setIsOpen,
    placement: position,
    middleware: [offset(offsetValue), ...(position ? [] : [autoPlacement()])],
    whileElementsMounted: autoUpdate,
  })

  const hover = useHover(context, {
    move: false,
    delay: { open: 100, close: 0 },
    mouseOnly: true,
  })
  const focus = useFocus(context)
  const dismiss = useDismiss(context)
  const role = useRole(context, {
    role: "tooltip",
    enabled: relationship === "description",
  })

  const { getReferenceProps, getFloatingProps } = useInteractions([hover, focus, dismiss, role])

  const referenceProps = getReferenceProps()
  const childProps: Record<string, unknown> = {}

  if (relationship === "label") {
    childProps["aria-label"] = typeof text === "string" ? text : undefined
  } else if (relationship === "description") {
    childProps["aria-describedby"] = context.floatingId
  }

  const handleTouchEnd = (event: React.TouchEvent) => {
    const originalOnTouchEnd = (children.props as Record<string, unknown>).onTouchEnd
    if (typeof originalOnTouchEnd === "function") {
      originalOnTouchEnd(event)
    }

    setTimeout(() => setIsOpen(false), 10)
  }

  const handleMouseOver = (event: React.MouseEvent) => {
    const originalOnMouseEnter = (children.props as Record<string, unknown>).onMouseEnter
    if (typeof originalOnMouseEnter === "function") {
      originalOnMouseEnter(event)
    }

    if (openTimeoutRef.current) {
      clearTimeout(openTimeoutRef.current)
      openTimeoutRef.current = null
    }
  }

  // Merge refs to support both Tooltip positioning and parent ref forwarding
  const mergeRefs = (...refs: (Ref<unknown> | undefined)[]) => {
    return (node: unknown) => {
      refs.forEach((ref) => {
        if (typeof ref === "function") {
          ref(node)
        } else if (ref && typeof ref === "object") {
          ;(ref as React.MutableRefObject<unknown>).current = node
        }
      })
    }
  }

  const childRef = (children.props as Record<string, unknown>).ref as Ref<unknown> | undefined

  const clonedChild = cloneElement(children, {
    ...referenceProps,
    ...childProps,
    onTouchEnd: handleTouchEnd,
    onMouseEnter: handleMouseOver,
    ref: mergeRefs(refs.setReference, childRef),
  } as Record<string, unknown>)

  return (
    <>
      {clonedChild}
      {isOpen && (
        <FloatingPortal>
          <div
            ref={refs.setFloating}
            id={context.floatingId}
            style={{
              ...floatingStyles,
              visibility: isPositioned ? "visible" : "hidden",
            }}
            className={clsx(
              "z-overlay max-w-xs rounded-md bg-neutral-900 px-2 py-1 text-xs text-neutral-50 shadow-sm",
            )}
            {...getFloatingProps()}
          >
            {text}
          </div>
        </FloatingPortal>
      )}
    </>
  )
}

