export const authDevApiRoutes = new Hono<{
  Bindings: Env
  Variables: Variables
}>()

authDevApiRoutes.use("*", requireAuth)

const DEV_USER_ID = "00000000-0000-0000-0000-000000000000"
const DEV_GITHUB_ID = 999_999_999_999
const DEV_GITHUB_LOGIN = "dev-user"

async function ensureDevUser(env: Env): Promise<string> {
  const db = getDb(env)
  const now = new Date()
  const existingUser = await db.users.findByGitHubId(DEV_GITHUB_ID)

  if (existingUser) {
    await getKysely(env)
      .updateTable("users")
      .set({
        github_login: DEV_GITHUB_LOGIN,
        discovery_enabled: 0,
        is_admin: 1,
        repos_synced_at: now,
        last_visited_at: now,
      })
      .where("id", "=", existingUser.id)
      .execute()

    return existingUser.id
  }

  await getKysely(env)
    .insertInto("users")
    .values({
      id: DEV_USER_ID,
      github_id: DEV_GITHUB_ID,
      github_login: DEV_GITHUB_LOGIN,
      discovery_enabled: 0,
      is_admin: 1,
      repos_synced_at: now,
      last_visited_at: now,
    })
    .execute()

  return DEV_USER_ID
}

authDevOAuthRoutes.get("/login", async (c) => {
  if (!isLocalDev(c.env) || !c.env.BYPASS_GH_OAUTH) {
    return c.notFound()
  }

  const userId = await ensureDevUser(c.env)
  const sessionToken = await createSession(c.env.ENTIRE_CACHE, userId)

  setCookie(c, "session", sessionToken, {
    httpOnly: true,
    secure: false,
    sameSite: "Lax",
    path: "/",
    maxAge: 60 * 60 * 24 * 7,
  })

  setCookie(c, "csrf", crypto.randomUUID(), {
    httpOnly: false,
    secure: false,
    sameSite: "Lax",
    path: "/",
    maxAge: 60 * 60 * 24 * 7,
  })

  return c.redirect(c.env.FRONTEND_BASE_URL)
})

authDevApiRoutes.post("/bootstrap-admin", async (c) => {
  if (!isLocalDev(c.env)) {
    return c.notFound()
  }

  const userId = c.get("userId")
  const db = getDb(c.env)
  const user = await db.users.findById(userId)

  if (!user) {
    return c.json({ error: "User not found" }, 404)
  }

  if (!user.is_admin) {
    await db.users.setAdmin(userId, true)
    await c.env.ENTIRE_CACHE.delete(`user:${userId}`)
  }

  return c.json({ is_admin: true })
})

