export async function ensureTrailsSynced(
  db: Db,
  repoId: string,
  repoFullName: string,
  token: string,
): Promise<boolean> {
  // Check if this repo has already been synced
  const alreadySynced = await db.repos.isTrailsSynced(repoId)
  if (alreadySynced) {
    return true
  }

  // Try to sync from git
  const result = await syncRepoTrails(db, repoId, repoFullName, token)
  return result.status === "ok" || result.status === "skipped"
}

