    !isBranchOutOfDate(mergeability) &&
    liveChecksAllowMerge
  // Approval is per-reviewer: anyone who hasn't approved yet can still approve,
  // even after another reviewer has approved.
  const canApprove = isOpenTrail && !hasViewerApproved(trail.reviewers, viewerLogin)

  if (!showMergeAction && !canApprove) return null

  return (
    <div className={fullWidth ? "flex flex-col gap-2" : "flex items-center gap-2"}>
      {showMergeAction ? (
        <Button
          size="small"
          variant={canMerge ? "attention" : "outline"}
          onClick={onMergeChanges}
          disabled={!canMerge || isMerging}
          className={fullWidth ? "w-full" : undefined}
        >
          {isMerging ? "Merging..." : "Merge changes"}
        </Button>
      ) : null}
      {canApprove ? (
        <Button
          size="small"
          variant={canMerge ? "outline" : "attention"}
          onClick={handleApprove}
          disabled={approvalMutation.isPending}
          className={fullWidth ? "w-full" : undefined}
        >
          {approvalMutation.isPending ? "Approving..." : "Approve"}
        </Button>
      ) : null}
    </div>
  )
}

