            <span>Threads</span>
            <Kbd className="pointer-coarse:hidden">T</Kbd>
          </Button>
        </DialogTrigger>
        <TrailThreadsPanel
          org={org}
          repo={repo}
          number={number}
          username={username}
          initialThreadId={defaultThreadId}
          focusedThreadId={focusedThreadId}
        />
      </Dialog>
    </div>
  )
}

