import { useEffect, useRef, useState, ReactNode } from "react"

import { CheckmarkIcon, CopyIcon } from "@/components/icons"
import { copyToClipboard } from "@/lib/clipboard"

interface CopyCodeProps {
  code: string
  prefix?: ReactNode
  onCopy?: () => void
  size?: "sm" | "lg"
}

export function CopyCode({ code, prefix, onCopy, size = "sm" }: CopyCodeProps) {
  const isLg = size === "lg"
  const [copied, setCopied] = useState(false)
  const copyTimeoutRef = useRef<number | null>(null)

  useEffect(() => {
    return () => {
      if (copyTimeoutRef.current) {
        clearTimeout(copyTimeoutRef.current)
      }
    }
  }, [])

  const handleCopy = async () => {
    if (copyTimeoutRef.current) {
      clearTimeout(copyTimeoutRef.current)
    }
    const success = await copyToClipboard(code)
    if (success) {
      setCopied(true)
      copyTimeoutRef.current = window.setTimeout(() => setCopied(false), 2000)
    }
    onCopy?.()
  }

  return (
    <div
      role="group"
      aria-label="Copy code"
      className={`floating-control-frame w-full rounded-xl ${isLg ? "h-14" : "h-11"}`}
    >
      {/* Wrapper reserves and paints the 1px ring inside the copy control. */}
      <div className="flex size-full items-stretch rounded-[calc(var(--radius-xl)-1px)] floating-control-surface">
        {prefix}
        <code
          className={`flex w-0 flex-1 items-center overflow-x-auto font-mono whitespace-nowrap text-muted ${
            isLg ? "px-3 text-sm sm:px-5" : "px-3 text-xs"
          }`}
          style={{ scrollbarWidth: "none", msOverflowStyle: "none" }}
        >
          {code}
        </code>
        <button
          onClick={handleCopy}
          className={`shrink-0 cursor-pointer rounded-r-[calc(var(--radius-xl)-1px)] border-l border-default transition-colors focus:outline-none focus-visible:outline-2 focus-visible:-outline-offset-1 focus-visible:outline-focus ${
            isLg ? "px-3 sm:px-5" : "px-3"
          } ${copied ? "text-green-600" : "text-muted hover:bg-floating-hover hover:text-default"}`}
          aria-label="Copy to clipboard"
        >
          {copied ? <CheckmarkIcon /> : <CopyIcon />}
        </button>
        <span aria-live="polite" className="sr-only">
          {copied ? "Copied to clipboard" : ""}
        </span>
      </div>
    </div>
  )
}

