interface DialogContextValue {
  open: boolean
  setOpen: (open: boolean) => void
  context: FloatingContext
  refs: ReturnType<typeof useFloating>["refs"]
  getFloatingProps: (userProps?: React.HTMLProps<HTMLElement>) => Record<string, unknown>
  labelId?: string
  descriptionId?: string
  setLabelId: (id?: string) => void
  setDescriptionId: (id?: string) => void
}

const DialogContext = createContext<DialogContextValue | null>(null)

const useDialogContext = () => {
  const context = useContext(DialogContext)
  if (!context) {
    throw new Error("Dialog components must be used within a Dialog")
  }
  return context
}

type SetStateFn = (open: boolean) => void

interface DialogProps {
  children: ReactNode
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: SetStateFn
}

const composeEventHandlers =
  <Event extends { defaultPrevented: boolean }>(
    theirHandler: ((event: Event) => void) | undefined,
    ourHandler: (event: Event) => void,
  ) =>
  (event: Event) => {
    theirHandler?.(event)
    if (!event.defaultPrevented) {
      ourHandler(event)
    }
  }

export function Dialog({ children, open: controlledOpen, defaultOpen, onOpenChange }: DialogProps) {
  const [uncontrolledOpen, setUncontrolledOpen] = useState(defaultOpen ?? false)
  const open = controlledOpen ?? uncontrolledOpen

  const setOpen = useCallback<SetStateFn>(
    (nextOpen) => {
      if (controlledOpen === undefined) {
        setUncontrolledOpen(nextOpen)
      }
      onOpenChange?.(nextOpen)
    },
    [controlledOpen, onOpenChange],
  )

  const { context, refs } = useFloating({
    open,
    onOpenChange: setOpen,
    whileElementsMounted: autoUpdate,
  })

  const dismiss = useDismiss(context, {
    outsidePress: true,
    escapeKey: true,
  })
  const role = useRole(context, { role: "dialog" })

  const { getFloatingProps } = useInteractions([dismiss, role])

  const [labelId, setLabelId] = useState<string>()
  const [descriptionId, setDescriptionId] = useState<string>()

  const value = useMemo<DialogContextValue>(
    () => ({
      open,
      setOpen,
      context,
      refs,
      getFloatingProps,
      labelId,
      descriptionId,
      setLabelId,
      setDescriptionId,
    }),
    [open, setOpen, context, refs, getFloatingProps, labelId, descriptionId],
  )

  return <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
}

interface DialogTriggerProps {
  children: ReactNode
  asChild?: boolean
}

export function DialogTrigger({ children, asChild }: DialogTriggerProps) {
  const { refs, setOpen, open, context } = useDialogContext()

  if (asChild) {
    if (!isValidElement(children)) {
      throw new Error("DialogTrigger with asChild requires a single React element child")
    }
    const child = children as ReactElement<{
      onClick?: (event: React.MouseEvent) => void
    }>
    return cloneElement(child, {
      ref: refs.setReference,
      onClick: composeEventHandlers(child.props.onClick, () => setOpen(true)),
      "aria-haspopup": "dialog",
      "aria-expanded": open,
      "aria-controls": context?.floatingId,
    } as Record<string, unknown>)
  }

  return (
    <Button
      ref={refs.setReference as Ref<HTMLButtonElement>}
      onClick={() => setOpen(true)}
      aria-haspopup="dialog"
      aria-expanded={open}
      aria-controls={context?.floatingId}
    >
      {children}
    </Button>
  )
}

