 * GitSourceUnavailableError are caught and the same call is retried against
 * the fallback. Anything else propagates — real bugs aren't masked.
 *
 * This is the early-ramp safety net documented in the plan: every Git read
 * has a path back to GitHub if go-git-api is unavailable, until the metrics
 * show that's no longer needed and the fallback can be deleted.
 */
export function wrapWithFallback(
  primary: GitSource,
  fallback: GitSource,
  repoFullName?: string,
): GitSource {
  function wrap<F extends (...args: never[]) => Promise<unknown>>(
    methodName: string,
    primaryFn: F,
    fallbackFn: F,
  ): F {
    return (async (...args: Parameters<F>) => {
      try {
        return await primaryFn(...args)
      } catch (err) {
        if (!(err instanceof GitSourceUnavailableError)) throw err
        console.log(`[git-source] fallback method=${methodName} reason=${err.reason}`)
        trace.getActiveSpan()?.addEvent("git_source.fallback", {
          "git_source.repo": repoFullName ?? "",
          "git_source.capability": methodName,
          "git_source.reason": err.reason,
        })
        return fallbackFn(...args)
      }
    }) as F
  }

  return {
    getFilesAtCommit: wrap(
      "getFilesAtCommit",
      primary.getFilesAtCommit.bind(primary),
      fallback.getFilesAtCommit.bind(fallback),
    ),
    listCommits: wrap(
      "listCommits",
      primary.listCommits.bind(primary),
      fallback.listCommits.bind(fallback),
    ),
    listDAG: wrap("listDAG", primary.listDAG.bind(primary), fallback.listDAG.bind(fallback)),
    resolveRef: wrap(
      "resolveRef",
      primary.resolveRef.bind(primary),
      fallback.resolveRef.bind(fallback),
    ),
    listBranches: wrap(
      "listBranches",
      primary.listBranches.bind(primary),
      fallback.listBranches.bind(fallback),
    ),
    compareBranchStatus: wrap(
      "compareBranchStatus",
      primary.compareBranchStatus.bind(primary),
      fallback.compareBranchStatus.bind(fallback),
    ),
    compare: wrap("compare", primary.compare.bind(primary), fallback.compare.bind(fallback)),
    mergeBase: wrap(
      "mergeBase",
      primary.mergeBase.bind(primary),
      fallback.mergeBase.bind(fallback),
    ),
    // Optional streaming method — pass through from primary if available.
    // No fallback wrapper needed: callers gate on presence before use.
    ...(primary.streamFileAtCommit
      ? { streamFileAtCommit: primary.streamFileAtCommit.bind(primary) }
      : {}),
  }
}

/**
 * Wrap a GitSource so every successful operation emits a `git_source.served`
 * span event tagged with the backend that served it.
 *
 * This is the denominator for the migration metric: the existing
 * `git_source.fallback` event only counts go-git-api failures (the numerator
 * of "still on GitHub"), but without a per-operation total there's no way to
 * compute what *share* of Git reads GitHub served — so a slow drift back onto
 * GitHub would be invisible. Tagging every served op closes that gap:
 *
 *   COUNT(git_source.served) GROUP BY git_source.backend   // share over time
 *
