export function instrumentBackend(
  source: GitSource,
  backend: GitSourceBackend,
  repoFullName?: string,
): GitSource {
  function served(capability: string): void {
    trace.getActiveSpan()?.addEvent("git_source.served", {
      "git_source.backend": backend,
      "git_source.capability": capability,
      "git_source.repo": repoFullName ?? "",
    })
  }
  function wrap<F extends (...args: never[]) => Promise<unknown>>(capability: string, fn: F): F {
    return (async (...args: Parameters<F>) => {
      const result = await fn(...args)
      served(capability)
      return result
    }) as F
  }

  return {
    getFilesAtCommit: wrap("getFilesAtCommit", source.getFilesAtCommit.bind(source)),
    listCommits: wrap("listCommits", source.listCommits.bind(source)),
    listDAG: wrap("listDAG", source.listDAG.bind(source)),
    resolveRef: wrap("resolveRef", source.resolveRef.bind(source)),
    listBranches: wrap("listBranches", source.listBranches.bind(source)),
    compareBranchStatus: wrap("compareBranchStatus", source.compareBranchStatus.bind(source)),
    compare: wrap("compare", source.compare.bind(source)),
    mergeBase: wrap("mergeBase", source.mergeBase.bind(source)),
    // Streaming method is lazy; tag at invocation since the backend is fixed
    // by then and the served signal is the call, not iteration completion.
    ...(source.streamFileAtCommit
      ? {
          streamFileAtCommit: ((
            ...args: Parameters<NonNullable<GitSource["streamFileAtCommit"]>>
          ) => {
            served("streamFileAtCommit")
            return source.streamFileAtCommit!(...args)
          }) as NonNullable<GitSource["streamFileAtCommit"]>,
        }
