export function shouldShowTrailBuildView({
  status,
  filesChanged,
  isFilesError,
}: {
  status: TrailDetail["status"] | undefined
  filesChanged: number | null
  isFilesError: boolean
}) {
  if (filesChanged !== null && filesChanged > 0) return true
  if (isFilesError) return true
  return !!status && status !== "merged" && status !== "closed"
}

export function getTrailCompareRefs(
  trail:
    | Pick<TrailDetail, "base" | "branch" | "status" | "merge_base_sha" | "head_sha">
    | undefined,
): { base: string; head: string; enabled: boolean } {
  if (!trail) return { base: "main", head: "", enabled: false }

  const snapshotBase = trail.merge_base_sha
  const snapshotHead = trail.head_sha
  if ((trail.status === "merged" || trail.status === "closed") && snapshotBase && snapshotHead) {
    return { base: snapshotBase, head: snapshotHead, enabled: true }
  }

  return {
    base: trail.base || "main",
    head: trail.branch ?? "",
    enabled: !!trail.branch,
  }
}

