  if (path === "/api/v1/preferences/repos/recent") return sendJson(res, req, 200, repoPreferences)
  if (path === "/api/v1/preferences/diff-view") return sendJson(res, req, 200, diffView)
  if (path === "/api/v1/preferences/filter-tabs") return sendJson(res, req, 200, filterTabs)

