  if (path === "/api/v1/trails/gh/entireio/cli/650/files") return sendJson(res, req, 200, files)
  if (path === "/api/v1/trails/gh/entireio/cli/650/threads") return sendJson(res, req, 200, emptyThreads)
  if (path === "/api/v1/trails/gh/entireio/cli/650/timeline") return sendJson(res, req, 200, emptyTimeline)
  if (path === "/api/v1/trails/gh/entireio/cli/650/mergeability") return sendJson(res, req, 200, mergeability)
