function isSessionAlreadyGoneError(error: unknown): boolean {
  return error instanceof ApiError && error.status === 401
}

export function AuthProvider({ children }: { children: ReactNode }) {
  const queryClient = useQueryClient()
  const posthog = usePostHog()

  const [user, setUser] = useState<AuthUser | null>(null)
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false)
  const [shouldCheckSession, setShouldCheckSession] = useState<boolean>(true)

  const seedRepoPreferencesCache = useCallback(
    (authUser: AuthUser) => {
      queryClient.setQueryData(getApiV1PreferencesReposQueryKey(), authUser.repo_preferences)
    },
    [queryClient],
  )

  // TODO: Extract PostHogPersonProperties to a shared package so this stays in sync
  // with the server-side type in api/src/lib/posthog.ts (used for local flag evaluation).
  const identifyPostHogUser = useCallback(
    (authUser: AuthUser) => {
      posthog.identify(authUser.id, {
        github_login: authUser.github_login,
        discovery_enabled: authUser.discovery_enabled,
        is_admin: authUser.is_admin,
        is_entirehq_member: authUser.is_entirehq_member,
        $created_at: authUser.created_at,
      })
    },
    [posthog],
  )

  const persistAuth = useCallback(
    (authUser: AuthUser) => {
      setUser(authUser)
      setIsAuthenticated(true)
      setShouldCheckSession(false)
      queryClient.setQueryData(["auth", "me"], authUser)
      seedRepoPreferencesCache(authUser)
      identifyPostHogUser(authUser)
    },
    [identifyPostHogUser, queryClient, seedRepoPreferencesCache],
  )

  const clearAuth = useCallback(() => {
    setUser(null)
    setIsAuthenticated(false)
    setShouldCheckSession(false)
    queryClient.removeQueries({ queryKey: ["auth"] })
    queryClient.cancelQueries({ queryKey: ["auth"] })
    queryClient.removeQueries({ queryKey: getApiV1PreferencesReposQueryKey() })
    queryClient.removeQueries({ queryKey: ["preferences"] })
  }, [queryClient])

  // Update user data without re-fetching (e.g. after toggling admin)
  const updateUser = useCallback(
    (authUser: AuthUser) => {
      setUser(authUser)
      queryClient.setQueryData(["auth", "me"], authUser)
      seedRepoPreferencesCache(authUser)
      identifyPostHogUser(authUser)
    },
    [identifyPostHogUser, queryClient, seedRepoPreferencesCache],
  )

  // GitHub OAuth login - just redirect, no mutation needed
  const login = useCallback((next?: string) => {
    startLogin(next)
  }, [])

  const completeLogout = useCallback(
    (redirectTo: string | null) => {
      clearPersistentState()
      posthog.reset()
      if (redirectTo) {
        window.location.replace(redirectTo)
        return
      }
      clearAuth()
    },
    [clearAuth, posthog],
  )

  const logout = useCallback(
    async ({ redirectTo = "/login" }: LogoutOptions = {}) => {
      try {
        await logoutRequest()
      } catch (error) {
        if (isSessionAlreadyGoneError(error)) {
          completeLogout(redirectTo)
          return
        }

        const logoutError = error instanceof Error ? error : new Error("Unknown logout error")
        posthog.captureException(logoutError, { action: "logout" })
        console.error("Logout error:", error)
        return
      }

      completeLogout(redirectTo)
    },
    [completeLogout, posthog],
  )

  // Check if we have an active session on mount (only once)
  const meQuery = useQuery<AuthUser, Error>({
    queryKey: ["auth", "me"],
    queryFn: fetchCurrentUser,
    enabled: shouldCheckSession,
    retry: false,
    staleTime: Infinity,
    refetchOnMount: false,
    refetchOnWindowFocus: false,
  })

  // Update auth state when user data is fetched
  useEffect(() => {
    if (meQuery.data && shouldCheckSession) {
      persistAuth(meQuery.data)
    } else if (meQuery.isError && shouldCheckSession) {
      clearAuth()
    }
  }, [meQuery.data, meQuery.isError, shouldCheckSession, persistAuth, clearAuth])

  const isVerifying = shouldCheckSession || meQuery.isFetching

  const value = useMemo<AuthContextValue>(
    () => ({
      isAuthenticated,
      user,
      login,
      logout,
      updateUser,
      isLoggingIn: false, // No loading state for redirect-based auth
      loginError: null, // Errors handled by OAuth flow
      isVerifying,
    }),
    [isAuthenticated, user, login, logout, updateUser, isVerifying],
  )

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>
}

