function sendJson(res, req, status, body) {
  const origin = req.headers.origin || "*"
  res.writeHead(status, {
    "content-type": "application/json; charset=utf-8",
    "access-control-allow-origin": origin,
    "access-control-allow-credentials": "true",
    "access-control-allow-methods": "GET,POST,PUT,PATCH,DELETE,OPTIONS",
    "access-control-allow-headers": req.headers["access-control-request-headers"] || "content-type,x-csrf-token",
    vary: "Origin",
  })
  res.end(JSON.stringify(body))
}

function sendNoContent(res, req) {
  const origin = req.headers.origin || "*"
  res.writeHead(204, {
    "access-control-allow-origin": origin,
    "access-control-allow-credentials": "true",
    "access-control-allow-methods": "GET,POST,PUT,PATCH,DELETE,OPTIONS",
    "access-control-allow-headers": req.headers["access-control-request-headers"] || "content-type,x-csrf-token",
    vary: "Origin",
  })
  res.end()
}

function route(req, res) {
  const url = new URL(req.url || "/", `http://${req.headers.host || "localhost"}`)
  const path = url.pathname

  if (req.method === "OPTIONS") {
    sendNoContent(res, req)
    return
  }

  if (path === "/api/v1/auth/me") return sendJson(res, req, 200, user)
  if (path === "/api/v1/dev/auth/bootstrap-admin") return sendJson(res, req, 200, { is_admin: true })
  if (path === "/api/v1/cache/repos") return sendJson(res, req, 200, repos)
  if (path === "/api/v1/cache/sync-status") return sendJson(res, req, 200, { status: "idle" })
  if (path === "/api/v1/cache/entireio/cli/checkpoint-status") {
    return sendJson(res, req, 200, { enabled: true, repo_full_name: "entireio/cli" })
  }
  if (path === "/api/v1/cache/entireio/cli/collaborators") {
    return sendJson(res, req, 200, { collaborators: [{ login: "peytonmontei" }] })
  }
  if (path === "/api/v1/cache/entireio/cli/compare") return sendJson(res, req, 200, compare)

  if (path === "/api/v1/preferences/repos") return sendJson(res, req, 200, repoPreferences)
  if (path === "/api/v1/preferences/repos/migrate") return sendJson(res, req, 200, repoPreferences)
  if (path === "/api/v1/preferences/repos/recent") return sendJson(res, req, 200, repoPreferences)
  if (path === "/api/v1/preferences/diff-view") return sendJson(res, req, 200, diffView)
  if (path === "/api/v1/preferences/filter-tabs") return sendJson(res, req, 200, filterTabs)

  if (path === "/api/v1/trails/gh/entireio/cli") {
    return sendJson(res, req, 200, {
      trails: [trail],
      total: 1,
      limit: 50,
      offset: 0,
      repo_full_name: "entireio/cli",
      default_branch: "main",
      updated_at: now,
      has_write_permission: true,
      has_app_installation: true,
    })
  }

  if (path === "/api/v1/trails/gh/entireio/cli/650") return sendJson(res, req, 200, trailDetail)
  if (path === "/api/v1/trails/gh/entireio/cli/650/files") return sendJson(res, req, 200, files)
  if (path === "/api/v1/trails/gh/entireio/cli/650/threads") return sendJson(res, req, 200, emptyThreads)
  if (path === "/api/v1/trails/gh/entireio/cli/650/timeline") return sendJson(res, req, 200, emptyTimeline)
  if (path === "/api/v1/trails/gh/entireio/cli/650/mergeability") return sendJson(res, req, 200, mergeability)
  if (path === "/api/v1/trails/gh/entireio/cli/650/checks") return sendJson(res, req, 200, checks)
  if (path === "/api/v1/trails/trail-local-650/reviews/comments") return sendJson(res, req, 200, emptyFindings)
  if (path === "/api/v1/trails/trail-local-650/reviews/events") return sendJson(res, req, 200, { events: [] })

  sendJson(res, req, 404, { error: `mock route not found: ${req.method} ${path}` })
}

const server = http.createServer(route)
server.on("upgrade", (_req, socket) => socket.destroy())
server.listen(port, "127.0.0.1", () => {
  console.log(`local trail preview API listening on http://localhost:${port}`)
})

