  return `entire trail resume ${number} --branch ${shellCommandArg(branch)}`
}

function shellCommandArg(value: string) {
  if (value === "") {
    return "''"
  }
  if (/^[A-Za-z0-9_\-./:]+$/.test(value)) {
    return value
  }
  return `'${value.split("'").join("'\\''")}'`
}

