function TrailApprovalAction({
  trail,
  org,
  repo,
  number,
  mergeability,
  checksStatus,
  isChecksLoading = false,
  isChecksError = false,
  viewerLogin,
  onMergeChanges,
  isMerging,
  fullWidth = false,
}: {
  trail: TrailDetail
  org: string
  repo: string
  number: number
  mergeability?: TrailMergeability
  checksStatus?: TrailChecksStatus
  isChecksLoading?: boolean
  isChecksError?: boolean
  viewerLogin?: string | null
  onMergeChanges: () => void
  isMerging: boolean
  fullWidth?: boolean
}) {
  const queryClient = useQueryClient()

  const approvalMutation = useMutation({
    mutationFn: () => submitTrailApproval(org, repo, number, "APPROVE"),
    onSettled: () => {
      queryClient.invalidateQueries({
        queryKey: ["github", "trails", org, repo, number],
      })
      queryClient.invalidateQueries({
        queryKey: ["github", "trails", org, repo, number, "approvals"],
      })
      queryClient.invalidateQueries({
        queryKey: ["github", "trails", org, repo, number, "mergeability"],
      })
      invalidateTrailListQueries(queryClient, org, repo)
    },
  })

  const handleApprove = useCallback(() => {
    approvalMutation.mutate()
  }, [approvalMutation])

  const isOpenTrail = trail.status === "open"
  // Merge only while the Trail is open and branch-backed, so stale cached
  // mergeability can't surface a Merge button on terminal/branchless Trails.
  const showMergeAction = isOpenTrail && !!trail.branch
  const liveChecksSummary = getLiveChecksGateSummary({
    checksStatus,
    isChecksLoading,
    isChecksError,
    hasMergeabilityFallback: !!mergeability,
  })
  const liveChecksAllowMerge = liveChecksSummary ? liveChecksSummary.tone === "success" : true
  const canMerge =
    showMergeAction &&
    !!mergeability?.mergeable &&
    !isBranchOutOfDate(mergeability) &&
    liveChecksAllowMerge
  // Approval is per-reviewer: anyone who hasn't approved yet can still approve,
  // even after another reviewer has approved.
  const canApprove = isOpenTrail && !hasViewerApproved(trail.reviewers, viewerLogin)

  if (!showMergeAction && !canApprove) return null

  return (
    <div className={fullWidth ? "flex flex-col gap-2" : "flex items-center gap-2"}>
      {showMergeAction ? (
        <Button
          size="small"
          variant={canMerge ? "attention" : "outline"}
          onClick={onMergeChanges}
          disabled={!canMerge || isMerging}
          className={fullWidth ? "w-full" : undefined}
        >
          {isMerging ? "Merging..." : "Merge changes"}
        </Button>
      ) : null}
      {canApprove ? (
        <Button
          size="small"
          variant={canMerge ? "outline" : "attention"}
          onClick={handleApprove}
          disabled={approvalMutation.isPending}
          className={fullWidth ? "w-full" : undefined}
        >
          {approvalMutation.isPending ? "Approving..." : "Approve"}
        </Button>
      ) : null}
    </div>
  )
}

