export function getTrailResumeCommand(number: number, repoFullName: string, branch: string) {
  return `entire trail resume ${number} --repo ${shellCommandArg(repoFullName)} --branch ${shellCommandArg(branch)}`
}

function shellCommandArg(value: string) {
  if (value === "") {
    return "''"
  }
  if (/^[A-Za-z0-9_\-./:]+$/.test(value)) {
    return value
  }
  return `'${value.split("'").join("'\\''")}'`
}

export function getTrailPullRequestUrl(org: string, repo: string, pullRequestNumber: number) {
  return `https://github.com/${org}/${repo}/pull/${pullRequestNumber}`
}

