	if convErr != nil || idx < 0 || idx >= len(items) {
		return fmt.Errorf("invalid selection %q", selected)
	}
	chosen := items[idx]

	if !chosen.isResumable() {
		fmt.Fprintf(w, "Session %s can't be resumed: %s.\n", chosen.state.SessionID, chosen.unresumableReason())
		return nil
