async function renderWithRouter(ui: ReactNode) {
  const rootRoute = createRootRoute({
    component: () => ui,
  })
  const router = createRouter({
    routeTree: rootRoute,
    history: createMemoryHistory({ initialEntries: ["/"] }),
  })

  await act(() => router.load())

  return {
    router,
    ...render(<RouterProvider router={router} />),
  }
}

