describe("getPendingBranchUpdateHeadShaQueryKey", () => {
  it("is not invalidated by broad trail detail invalidations", async () => {
    const queryClient = new QueryClient({
      defaultOptions: { queries: { retry: false }, mutations: { retry: false } },
    })
    const markerKey = getPendingBranchUpdateHeadShaQueryKey("entirehq", "entire.io", 1)

    queryClient.setQueryData(markerKey, {
      headSha: "updated-head-sha",
      hadChecksBeforeUpdate: true,
      createdAtMs: 1_000,
    })
    await queryClient.invalidateQueries({
      queryKey: ["github", "trails", "entirehq", "entire.io", 1],
    })

    expect(queryClient.getQueryData(markerKey)).toEqual({
      headSha: "updated-head-sha",
      hadChecksBeforeUpdate: true,
      createdAtMs: 1_000,
    })
    expect(queryClient.getQueryState(markerKey)?.isInvalidated).toBe(false)
  })
})

describe("shouldClearPendingBranchUpdateHead", () => {
  const pending = { headSha: "updated-head-sha", hadChecksBeforeUpdate: true, createdAtMs: 1_000 }

  it("does not clear while matching new-head checks are still absent before the settle timeout", () => {
    expect(
      shouldClearPendingBranchUpdateHead({
        pending,
        mergeability: makeMergeability({ head_sha: "updated-head-sha", checks_status: "success" }),
        checksStatus: {
          state: "none",
          head_sha: "updated-head-sha",
          total_count: 0,
          checks: [],
          automation: null,
        },
        nowMs: 2_000,
      }),
    ).toBe(false)
  })

  it("clears once checks for the new head have appeared", () => {
    expect(
      shouldClearPendingBranchUpdateHead({
        pending,
        mergeability: makeMergeability({ head_sha: "updated-head-sha", checks_status: "pending" }),
        checksStatus: {
          state: "pending",
          head_sha: "updated-head-sha",
          total_count: 1,
          checks: [],
          automation: null,
        },
      }),
    ).toBe(true)
  })

  it("clears after a bounded settle if checks never appear on the updated head", () => {
    expect(
      shouldClearPendingBranchUpdateHead({
        pending,
        mergeability: makeMergeability({ head_sha: "updated-head-sha", checks_status: "none" }),
        checksStatus: {
          state: "none",
          head_sha: "updated-head-sha",
          total_count: 0,
          checks: [],
          automation: null,
        },
        nowMs: 61_000,
      }),
    ).toBe(true)
  })

  it("clears immediately for branches that had no checks before updating", () => {
    expect(
      shouldClearPendingBranchUpdateHead({
        pending: { headSha: "updated-head-sha", hadChecksBeforeUpdate: false, createdAtMs: 1_000 },
        mergeability: makeMergeability({ head_sha: "updated-head-sha", checks_status: "none" }),
        checksStatus: {
          state: "none",
          head_sha: "updated-head-sha",
          total_count: 0,
          checks: [],
          automation: null,
        },
      }),
    ).toBe(true)
  })
})

