describe("TrailStatusBox", () => {
  it("shows gates for active trails with code changes", () => {
    expect(
      shouldShowTrailStatusBox({ status: "open", branch: "feature", has_code_changes: true }),
    ).toBe(true)
    expect(
      shouldShowTrailStatusBox({ status: "draft", branch: "feature", has_code_changes: true }),
    ).toBe(true)
    expect(shouldShowTrailStatusBox({ status: "open", branch: null, has_code_changes: true })).toBe(
      false,
    )
    expect(
      shouldShowTrailStatusBox({ status: "open", branch: "feature", has_code_changes: false }),
    ).toBe(false)
    expect(
      shouldShowTrailStatusBox(
        { status: "draft", branch: "feature", has_code_changes: false },
        true,
      ),
    ).toBe(true)
    expect(
      shouldShowTrailStatusBox({ status: "merged", branch: "feature", has_code_changes: true }),
    ).toBe(false)
    expect(
      shouldShowTrailStatusBox({ status: "closed", branch: "feature", has_code_changes: true }),
    ).toBe(false)
  })

  it("shows archived checks for terminal trails with a captured head SHA and code changes", () => {
    expect(shouldShowTrailTerminalChecks({ status: "merged", head_sha: "abc123" }, true)).toBe(true)
    expect(shouldShowTrailTerminalChecks({ status: "closed", head_sha: "abc123" }, true)).toBe(true)
    expect(shouldShowTrailTerminalChecks({ status: "merged", head_sha: null }, true)).toBe(false)
    expect(shouldShowTrailTerminalChecks({ status: "merged", head_sha: "abc123" }, false)).toBe(
      false,
    )
    expect(shouldShowTrailTerminalChecks({ status: "open", head_sha: "abc123" }, true)).toBe(false)
  })

  it("hides the code summary header while keeping gate content", () => {
    renderTrailStatusBox({
      trail: {
        ...baseTrail,
        status: "open",
        branch: "dip/generic-timeline",
        has_code_changes: true,
      },
    })

    expect(screen.getByText("Gates")).toBeInTheDocument()
    expect(screen.getByText("Peer review")).toBeInTheDocument()
    expect(screen.getByText("Passing checks")).toBeInTheDocument()
    expect(screen.getByText("Findings addressed")).toBeInTheDocument()
    expect(screen.queryByRole("button", { name: /Peer review/ })).not.toBeInTheDocument()
    expect(screen.queryByRole("button", { name: /Passing checks/ })).not.toBeInTheDocument()
    expect(screen.queryByRole("button", { name: /Findings addressed/ })).not.toBeInTheDocument()
    expect(screen.queryByText("Needs approval")).not.toBeInTheDocument()
    expect(screen.queryByText("1 commit")).not.toBeInTheDocument()
    expect(screen.queryByText("dip/generic-timeline")).not.toBeInTheDocument()
  })

  it("does not count stale findings as findings to address", () => {
    renderTrailStatusBox({
      trail: {
        ...baseTrail,
        status: "open",
        branch: "dip/generic-timeline",
        has_code_changes: true,
      },
      findings: [makeFinding({ stale_outcome: "stale", status: "open" })],
    })

    expect(screen.getByText("No open findings")).toBeInTheDocument()
    expect(screen.queryByText("1 finding to address")).not.toBeInTheDocument()
  })

  it("shows a reviewing-in-progress state while a review runner is active", () => {
    renderTrailStatusBox({
      trail: {
        ...baseTrail,
        status: "open",
        branch: "dip/generic-timeline",
        has_code_changes: true,
      },
      findings: [],
      isReviewRunning: true,
    })

    expect(screen.getByText("Reviewing changes…")).toBeInTheDocument()
    expect(screen.queryByText("No open findings")).not.toBeInTheDocument()
  })
})

